SINA_SMART["cellbio1-methods"] = {"lecture":"cellbio1-methods","title":"Cell study methods: microscopy, histology and cell culture","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"cellbio1-methods:e0","text":"Three levels: morphological, biochemical, physiological (culture).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-methods:e1","text":"LM: condenser, objective (4-100×), eyepiece (10×); ~1,000×.","topic":"Microscopes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-methods:e2","text":"Fluorescence: UV lamp, labelled cells; confocal: higher resolution.","topic":"Microscopes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-methods:e3","text":"Inverted: living unstained cultured cells (IVF embryos).","topic":"Microscopes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-methods:e4","text":"TEM: electron beam, magnetic lenses, vacuum; ~100,000×, ultrastructure.","topic":"Microscopes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-methods:e5","text":"SEM: 3D surface images.","topic":"Microscopes","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-methods:e6","text":"Smear: spread, air-dry, MGG stain.","topic":"Preparing samples","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-methods:e7","text":"Histology: sampling, fixation (Bouin), paraffin inclusion, 3-4 µm sections, staining.","topic":"Preparing samples","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-methods:e8","text":"HE: haematoxylin nuclei blue, eosin cytoplasm pink; HES fibres yellow.","topic":"Preparing samples","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"cellbio1-methods:e9","text":"Culture: 37 °C, pH 7-7.4, 5% CO₂, sterile hood, RPMI/MEM; trypsin dissociation.","topic":"Cell culture","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1dhfl12":"a","1gxuay2":"a","1fx5a4k":"a","gb659f":"a","1b6pcu":"a","1exig37":"a","a40pvu":"a","hp2ar3":"a","h333y1":"a","17swce2":"a","1tj6lxm":"a","lyiosf":"a","10kva3p":"a","14wm3yh":"a","17ygrmr":"a","1pf7ujc":"x"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"cellbio1-methods:e0":{"s":0,"u":["Three levels: morphological, biochemical, physiological (culture).","Cells are studied at three levels: morphological (microscopy), biochemical (electrophoresis, chromatography, ELISA: see biochemistry) and physiological ( cell culture )."],"dp":[]},"cellbio1-methods:e1":{"s":1,"u":["LM: condenser, objective (4-100×), eyepiece (10×); ~1,000×.","Light microscope (LM) : base, arm and optical tube; light source below; three lenses: condenser (focuses light on the specimen), objective (4×, 10×, 100×) and eyepiece (10×)."],"dp":[]},"cellbio1-methods:e2":{"s":1,"u":["Fluorescence: UV lamp, labelled cells; confocal: higher resolution.","Limits: cannot show labelling or living unstained cells, so special light microscopes exist: fluorescence microscope (UV lamp detects fluorescent labels; helps type cancers), confocal microscope (improved fluorescence with higher resolution and better localisation) and inverted microscope (lamp on top, objective under the stage; observes living, unstained cultured cells , e.g. embryos in assisted reproduction; uses phase-contrast optics)."],"dp":[]},"cellbio1-methods:e3":{"s":1,"u":["Inverted: living unstained cultured cells (IVF embryos).","Limits: cannot show labelling or living unstained cells, so special light microscopes exist: fluorescence microscope (UV lamp detects fluorescent labels; helps type cancers), confocal microscope (improved fluorescence with higher resolution and better localisation) and inverted microscope (lamp on top, objective under the stage; observes living, unstained cultured cells , e.g. embryos in assisted reproduction; uses phase-contrast optics)."],"dp":[]},"cellbio1-methods:e4":{"s":1,"u":["TEM: electron beam, magnetic lenses, vacuum; ~100,000×, ultrastructure.","Transmission electron microscope (TEM) : same layout but an electron beam instead of a lamp, three magnetic lenses , and a vacuum pump so electrons are not deflected; about 100,000× , showing ultrastructure (organelles; e.g. demyelinated axons with macrophages in mad cow disease).","Scanning electron microscope (SEM) : electron beam, detector, image converter and monitor give 3D surface images of whole cells, bacteria and viruses (red cells, lymphocytes)."],"dp":[{"h":"Why electron microscopes see more","t":"What limits a microscope is the wavelength of what it uses to 'see'. Visible light cannot separate structures closer than about 0.2 µm, so organelles blur together. Electrons have a far shorter wavelength, so an electron microscope can separate much finer detail, revealing membranes and organelles; the price is a vacuum and dead, specially prepared samples. Source: the lecture's light and special microscope limits slide."}]},"cellbio1-methods:e5":{"s":1,"u":["SEM: 3D surface images.","Scanning electron microscope (SEM) : electron beam, detector, image converter and monitor give 3D surface images of whole cells, bacteria and viruses (red cells, lymphocytes)."],"dp":[]},"cellbio1-methods:e6":{"s":2,"u":["Smear: spread, air-dry, MGG stain.","Blood smear: place a drop at the edge of a slide, spread with another slide, air-dry , stain with MGG (May-Grünwald-Giemsa) ."],"dp":[]},"cellbio1-methods:e7":{"s":2,"u":["Histology: sampling, fixation (Bouin), paraffin inclusion, 3-4 µm sections, staining.","Histology for solid tissues (liver, skin, heart, muscle, bone): sampling → fixation → inclusion (embedding) → sectioning → staining .","Inclusion replaces water with paraffin to harden the tissue for thin sections."],"dp":[]},"cellbio1-methods:e8":{"s":2,"u":["HE: haematoxylin nuclei blue, eosin cytoplasm pink; HES fibres yellow.","Staining creates contrast between transparent structures: basic dye haematoxylin stains nuclei blue , acidic eosin stains cytoplasm pink ; standard HE ; HES adds saffron to show fibres in yellow (fibrosis)."],"dp":[{"h":"Why tissues are stained","t":"Most cell structures are colourless and have similar refractive indices, so an unstained section looks almost blank. Haematoxylin, a basic dye, binds acidic structures such as DNA in the nucleus, and eosin, an acidic dye, binds basic proteins in the cytoplasm. The blue-pink contrast lets pathologists read tissue architecture and spot tumours. Source: the lecture's staining slides."}]},"cellbio1-methods:e9":{"s":3,"u":["Culture: 37 °C, pH 7-7.4, 5% CO₂, sterile hood, RPMI/MEM; trypsin dissociation.","Conditions: 37 °C , pH 7-7.4 in a CO₂ (5%) incubator , sterility (laminar flow hood, germicidal UV), sterile single-use plastic vessels, media such as MEM or RPMI 1640 (water, salts, vitamins, amino acids, glucose, antibiotics, fetal calf serum, growth factors).","Steps (under the hood): take living tissue, mechanical dissociation , enzymatic dissociation (trypsin, collagenase), count cells , add medium (~10⁶ cells per 10 mL), incubate, count daily with the inverted microscope, and subculture into new flasks when cells exceed ~10⁶ per 10 mL."],"dp":[]}},"meta":{"1dhfl12":{"a":"recall","vg":"cellbio1-methods:e2/recall/1"},"1gxuay2":{"a":"recall","vg":"cellbio1-methods:e1/recall/1"},"1fx5a4k":{"a":"recall","vg":"cellbio1-methods:e2/recall/2"},"gb659f":{"a":"recall","vg":"cellbio1-methods:e3/recall/1"},"1b6pcu":{"a":"relationship","vg":"cellbio1-methods:e4/relationship/1"},"1exig37":{"a":"recall","vg":"cellbio1-methods:e4/recall/1"},"a40pvu":{"a":"recall","vg":"cellbio1-methods:e5/recall/1"},"hp2ar3":{"a":"recall","vg":"cellbio1-methods:e6/recall/1"},"h333y1":{"a":"relationship","vg":"cellbio1-methods:e6/relationship/1"},"17swce2":{"a":"recall","vg":"cellbio1-methods:e7/recall/1"},"1tj6lxm":{"a":"recall","vg":"cellbio1-methods:e8/recall/1"},"lyiosf":{"a":"recall","vg":"cellbio1-methods:e8/recall/1"},"10kva3p":{"a":"recall","vg":"cellbio1-methods:e0/recall/1"},"14wm3yh":{"a":"recall","vg":"cellbio1-methods:e9/recall/1"},"17ygrmr":{"a":"recall","vg":"cellbio1-methods:e0/recall/2"}},"explRev":"e16b7d3a5c9d"};
